'use strict';
if (process.argv[1]?.endsWith('/assert-report-handler-topology.cjs')) {
 const fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
 const root='/workspace/scratch/253982db7f9e/pulse';
 const snapshot=require(path.join(root,'wasm/packages/cli/src/internal/report/snapshot'));
 const log=value=>fs.appendFileSync('/tmp/hex-report-trace.jsonl',JSON.stringify(value)+'\n');
 const hash=value=>createHash('sha256').update(value).digest('hex');
 const diff=(a,b)=>{const aa=new Map(a.records.map(x=>[x.file,x])),bb=new Map(b.records.map(x=>[x.file,x]));return [...new Set([...aa.keys(),...bb.keys()])].filter(k=>JSON.stringify(aa.get(k))!==JSON.stringify(bb.get(k))||a.tokens.get(k)!==b.tokens.get(k)).map(k=>({file:k,before:aa.get(k),after:bb.get(k),tokenBefore:a.tokens.get(k),tokenAfter:b.tokens.get(k)}));};
 const begin=snapshot.beginSnapshot;
 snapshot.beginSnapshot=function(project,...args){try{return begin(project,...args);}catch(error){log({phase:'begin',error:error.code,root:project.root});throw error;}};
 const finish=snapshot.finishSnapshot;
 snapshot.finishSnapshot=function(project,attempt,compiled){try{return finish(project,attempt,compiled);}catch(error){
  const details={phase:'finish',error:error.code,root:project.root};
  try {details.project=diff(attempt.current,snapshot.scan(project.root,{excluded:attempt.excluded}));details.workspace=diff(attempt.workspace,snapshot.workspaceControls(project.root));details.dependencies=[];for(const [key,{root,snapshot:before}] of attempt.dependencies.snapshots){const changed=diff(before,snapshot.scan(root,{packageFiles:true}));if(changed.length)details.dependencies.push({key,changed});}}catch(e){details.scanError=e.code||e.message;}
  log(details);throw error;
 }};
 const read=fs.readFileSync,write=fs.writeFileSync;
 const watched=file=>typeof file==='string'&&file.includes('/report-analytics-')&&(/\/src\/index.ts$/.test(file)||/\.wasm$/.test(file));
 fs.writeFileSync=function(file,data,...args){const r=write.call(this,file,data,...args);if(watched(file))log({op:'write',file,sha256:hash(data),bytes:Buffer.byteLength(data)});return r;};
 fs.readFileSync=function(file,...args){const r=read.call(this,file,...args);if(watched(file))log({op:'read',file,sha256:hash(r),bytes:Buffer.byteLength(r)});return r;};
 process.on('exit',code=>log({phase:'exit',code}));
}

'use strict';
if (process.argv[1]?.endsWith('/assert-report-handler-topology.cjs')) {
 const fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
 const root='/workspace/scratch/253982db7f9e/pulse';
 const snapshot=require(path.join(root,'wasm/packages/cli/src/internal/report/snapshot'));
 const log=value=>fs.appendFileSync('/tmp/hex-snapshot-trace.jsonl',JSON.stringify(value)+'\n');
 const hash=value=>createHash('sha256').update(value).digest('hex');
 const diff=(a,b)=>{const aa=new Map(a.records.map(x=>[x.file,x])),bb=new Map(b.records.map(x=>[x.file,x]));return [...new Set([...aa.keys(),...bb.keys()])].filter(k=>JSON.stringify(aa.get(k))!==JSON.stringify(bb.get(k))||a.tokens.get(k)!==b.tokens.get(k)).map(k=>({file:k,before:aa.get(k),after:bb.get(k),tokenBefore:a.tokens.get(k),tokenAfter:b.tokens.get(k)}));};
 const receipts=new Map(),resolve=snapshot.resolutionStart;
 snapshot.resolutionStart=function(root,...args){const r=resolve(root,...args);receipts.set(root,r);return r;};
 const begin=snapshot.beginSnapshot;
 snapshot.beginSnapshot=function(project,...args){try{return begin(project,...args);}catch(error){const detail={phase:'begin',error:error.code,root:project.root};try{const receipt=receipts.get(project.root);detail.receiptError=receipt?.error;detail.project=diff(receipt.snapshot,snapshot.scan(project.root,{excluded:receipt.excluded}));detail.workspace=diff(receipt.workspace,snapshot.workspaceControls(project.root));}catch(e){detail.scanError=e.code||e.message;}log(detail);throw error;}};
 const finish=snapshot.finishSnapshot;
 snapshot.finishSnapshot=function(project,attempt,compiled){try{return finish(project,attempt,compiled);}catch(error){
  const details={phase:'finish',error:error.code,root:project.root};
  try {const current=snapshot.scan(project.root,{excluded:attempt.excluded});details.project=diff(attempt.current,current);details.workspace=diff(attempt.workspace,snapshot.workspaceControls(project.root));details.dependencies=[];for(const [key,{root,snapshot:before}] of attempt.dependencies.snapshots){const changed=diff(before,snapshot.scan(root,{packageFiles:true}));if(changed.length)details.dependencies.push({key,changed});}
   details.projectModules=(compiled.reachableGraph?.modules||[]).filter(x=>x.kind==='project').map(x=>({path:x.path,compiled:x.contentHash,snapshot:current.records.find(r=>r.file===x.path)?.sha256,direct:x.packageName?null:hash(fs.readFileSync(path.join(project.root,x.path)))}));
   details.imported=require(path.join(root,'wasm/packages/compiler/src/canonical-project-compiler')).sourceInputsForCompiled(compiled);
  }catch(e){details.scanError=e.code||e.message;}
  log(details);throw error;
 }};
 process.on('exit',code=>log({phase:'exit',code}));
}

